from pathlib import Path
import subprocess,tempfile
R=Path(__file__).resolve().parents[1]
work=Path(tempfile.mkdtemp(prefix='r10_mock_scope_'))
pkg=work/'com/seu/socialworkcards';pkg.mkdir(parents=True)
(pkg/'MockExamEngine.java').write_bytes((R/'app/src/main/java/com/seu/socialworkcards/MockExamEngine.java').read_bytes())
(pkg/'Card.java').write_text('package com.seu.socialworkcards;import java.util.*;public class Card { public String id="",category="",questionType="",kind="",sourceModule="BASE",examSubjectScope="331,437"; public java.util.List<String> exactExamSources=new ArrayList<>(),recallExamSources=new ArrayList<>();public Card(String id,String type,String module,String scope){this.id=id;this.questionType=type;this.kind=type;this.sourceModule=module;this.examSubjectScope=scope;} }',encoding='utf-8')
(pkg/'CardRepository.java').write_text('package com.seu.socialworkcards;import java.util.*;public class CardRepository {public List<Card> cards=new ArrayList<>(),v24Cards=new ArrayList<>(),r10ExamCards=new ArrayList<>();public boolean isV24(Card c){return "V24_437".equals(c.sourceModule);}public boolean isR10(Card c){return "Z00_R10".equals(c.sourceModule);}public boolean isRealExam(Card c){return isR10(c);}public boolean isExactExam(Card c){return false;}public boolean isRecallExam(Card c){return false;}public boolean matchesExamSubject(Card c,String sub){if(isV24(c))return "437".equals(sub);if(isR10(c))return c.examSubjectScope.equals(sub) && !(c.id.equals("R10-031")||c.id.equals("R10-032"));return "331".equals(sub)||"437".equals(sub);}public String questionType(Card c){return c.questionType;}public String systemFrequency(Card c){return "中";}}',encoding='utf-8')
(pkg/'StudyStore.java').write_text('package com.seu.socialworkcards;import java.util.*;public class StudyStore{public static class State{public List<String> history=new ArrayList<>();public String tag="未学习";}public boolean isFavorite(String id){return false;}public String frequencyOverride(String id){return "";}public State state(String id){return new State();}}',encoding='utf-8')
(pkg/'ReviewEngine.java').write_text('package com.seu.socialworkcards;public class ReviewEngine {public double difficulty(Card c){return 0.5;}}',encoding='utf-8')
(pkg/'TestR10.java').write_text('package com.seu.socialworkcards;import java.util.*;public class TestR10{public static void main(String[]args){CardRepository r=new CardRepository();for(int i=0;i<378;i++)r.v24Cards.add(new Card(String.format("437M%03d",i+1),"名词解释","V24_437","437"));for(int i=0;i<55;i++){String type=i<15?"名词解释":i<30?"简答题":i<42?"论述题":"案例分析题";r.cards.add(new Card(String.format("C%04d",i+1),type,"BASE","331,437"));}r.r10ExamCards.add(new Card("R10-001","名词解释","Z00_R10","331"));r.r10ExamCards.add(new Card("R10-002","名词解释","Z00_R10","437"));r.r10ExamCards.add(new Card("R10-047","案例分析题","Z00_R10","437"));r.r10ExamCards.add(new Card("R10-064","论述题","Z00_R10","437"));r.r10ExamCards.add(new Card("R10-031","案例分析题","Z00_R10","437"));MockExamEngine m=new MockExamEngine(r,new StudyStore(),new ReviewEngine());boolean seen331=false,seen437=false;for(int i=0;i<300;i++)for(String sub:new String[]{"331","437"}){MockExamEngine.Paper p=m.generate(sub);for(MockExamEngine.Section s:p.sections)for(Card c:s.cards){if(c.id.equals("R10-031"))throw new AssertionError("abstract case in mock");if(c.sourceModule.equals("Z00_R10")){if(!c.examSubjectScope.equals(sub))throw new AssertionError("R10 cross-subject: "+c.id+" "+sub);if(sub.equals("331"))seen331=true;else seen437=true;}if(c.sourceModule.equals("V24_437") && !sub.equals("437"))throw new AssertionError("V24 leaked 331");}}if(!seen331||!seen437)throw new AssertionError("R10 not sampled");System.out.println("PASS 300x2 R10 isolation and V24 isolation");}}',encoding='utf-8')
a=subprocess.run(['javac','-encoding','UTF-8','-d',str(work)]+[str(q) for q in pkg.glob('*.java')],capture_output=True,text=True)
if a.returncode:raise SystemExit(a.stderr)
b=subprocess.run(['java','-cp',str(work),'com.seu.socialworkcards.TestR10'],capture_output=True,text=True)
if b.returncode:raise SystemExit(b.stdout+b.stderr)
print(b.stdout.strip())
